    return "tsconfig" if b == "tsconfig.json" else ("jsconfig" if b == "jsconfig.json" else "other")


def cnode(path, extends):
    return {"path": path, "contentSha256": _digest_of(path), "kind": node_kind(path),
            "extendsResolved": extends}


